scenes.code:
:root {
    --do: #D40000;
    --xanh: #0033CC;
    --hong: #FFD9E6;
    --vang-nhat: #FFFDE7;
    --vien: #9E9E9E;
}

* { box-sizing: border-box; }

body {
    margin: 0;
    padding: 32px 16px;
    font-family: Georgia, "Times New Roman", serif;
    background: #ffffff;
    display: flex;
    justify-content: center;
}

.khung-tho {
    width: min(640px, 100%);
    background: var(--vang-nhat);
    border: 1px solid var(--vien);
    padding: 24px;
    text-align: center;
}

.khung-tho h1 {
    margin: 0 0 20px;
    font-size: 26px;
    color: var(--do);
    background: var(--hong);
    padding: 6px 0;
    letter-spacing: 1px;
}

.kho {
    margin: 0;

     font-style: italic;
     font-size: 17px;
     line-height: 1.75;
}

.xanh { color: var(--xanh); }
.do      { color: var(--do); }

hr {
     width: 55%;
     margin: 16px auto;
     border: none;
     border-top: 1px solid var(--xanh);
}
